INSERT INTO `birthday_greetings` VALUES (6,'0000','demo-default','منه','أحمد',1,0,'ar','classic','romantic','{\"hero\": {\"quote\": \"\\\"عامك الجديد وعمري ما يكملوش غير بنور عينيكي وضحكة قلبك الصافية\\\"\", \"kicker\": \"احتفالاً بيوم ميلادك المميز 💖\", \"birthdate\": \"11 • 06 • 2009\", \"avatar_image\": null, \"avatar_title\": \"سامية\", \"banner_image\": \"/assets/images/birthday_banner.png\", \"avatar_subtitle\": \"سامية سر سعادتي وعمري 🌹\"}, \"album\": {\"title\": \"ALBUM OF MEMORIES • ألبوم الذكريات\", \"images\": [\"https://images.unsplash.com/photo-1518199266791-5375a83190b7?auto=format&fit=crop&q=80&w=1200\", \"https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&q=80&w=1200\", \"https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&q=80&w=1200\", \"https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&q=80&w=1200\", \"https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&q=80&w=1200\"], \"description\": \"صور محفورة في القلب، ولحظات لا تُنسى بتفاصيلها الجميلة. اضغطي على أي صورة لرؤيتها بوضوح وحفظها كذكرى مخلدة 🌹\", \"images_text\": \"https://images.unsplash.com/photo-1518199266791-5375a83190b7?auto=format&fit=crop&q=80&w=1200\\nhttps://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&q=80&w=1200\\nhttps://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&q=80&w=1200\\nhttps://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&q=80&w=1200\\nhttps://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&q=80&w=1200\"}, \"audio\": {\"url\": \"https://youtu.be/fJAPs63jZUE?si=VJONXhgbGkNrhtxj\"}, \"basic\": {\"passcode\": \"942026\"}, \"footer\": {\"text\": \"شكراً لمشاركتنا لحظاتكم السعيدة 🌹\", \"whatsapp\": \"201066787955\"}, \"letter\": {\"title\": \"رسالة حب سرية مخصصة لسمسة 💖\", \"description\": \"اضغطي على الختم في المنتصف لفتح الرسالة الخاصة والاستماع للألحان 💌\", \"love_phrase\": \"بحبكككككككككككككك 💗💗💗\", \"letter_title\": \"عيد ميلاد أحلى وأجمل وأطيب 17 في الدنيا كلها.. 🎂✨\", \"letter_content\": \"كل سنة وأنتِ طيبة يا أجمل حاجة حصلتلي في حياتي. النهار ده مش مجرد عيد ميلادك، ده يوم مميز عشان اتولدت فيه أغلى إنسانة في حياتي.\\n\\nكل سنة وأنتِ حبيبتي، وصاحبتي، وبنتي، وأجمل قدر ربنا كتبهولي. كل سنة وأنتِ جنبي، وسندي، وفرحتي. ربنا يديم ضحكتك السكر اللي بموت فيها دي وتفضل تنور أي مكان.\\n\\nربنا يسعد قلبك زي ما بتسعدي قلبي كل يوم. يا رب أفضل طول العمر أشوف الفرحة في عينيكي وأكون سبب في ابتسامتك. نفسي والله كل أعياد ميلادك نحتفل بيها سوا وإحنا بنحقق أحلامنا، وبإذن الله في يوم من الأيام أكون موجود جنبك ونحتفل بيه مع بعض.\"}, \"wishes\": {\"items\": [{\"tags\": [\"حبي الأبدي ✨\", \"حبنا بيكبر ❤️\"], \"text\": \"كل سنة وأنتِ جوة قلبي، كل عام وأنتِ حبي الأول والأخير وروحي وسر ضحكتي وسعادتي يا كل حياتي...\"}, {\"tags\": [\"دنيتي الجميلة 🌱\", \"سند وعمر 🙌\"], \"text\": \"يا رب يباركلي في عمرك يا حبيبتي، ويخلي أيامنا كلها حب وضحكة حلوة وراحة بال على طول سوا.\"}, {\"tags\": [\"عشق ملوش آخر 🌹\", \"نور عيوني 💫\"], \"text\": \"يا نور عيني ويا حتة من روحي، كل سنة وأنتِ طيبة ومعايا وجنبي، ومنورالي حياتي يا أغلى وأجمل ما عندي في الدنيا.\"}, {\"tags\": [\"نبض واحد 💞\", \"حبيبة قلبي 🔗\"], \"text\": \"أنتِ مش بس فرحة يوم ميلادك، أنتِ فرحة العمر كله اللي كنت بتمناها، ربنا يديمك ليا يا أحلى حاجة حصلتلي.\"}], \"title\": \"A PERSONAL WISH • أمنية خاصة\", \"items_text\": \"كل سنة وأنتِ جوة قلبي، كل عام وأنتِ حبي الأول والأخير وروحي وسر ضحكتي وسعادتي يا كل حياتي... | حبي الأبدي ✨, حبنا بيكبر ❤️\\nيا رب يباركلي في عمرك يا حبيبتي، ويخلي أيامنا كلها حب وضحكة حلوة وراحة بال على طول سوا. | دنيتي الجميلة 🌱, سند وعمر 🙌\\nيا نور عيني ويا حتة من روحي، كل سنة وأنتِ طيبة ومعايا وجنبي، ومنورالي حياتي يا أغلى وأجمل ما عندي في الدنيا. | عشق ملوش آخر 🌹, نور عيوني 💫\\nأنتِ مش بس فرحة يوم ميلادك، أنتِ فرحة العمر كله اللي كنت بتمناها، ربنا يديمك ليا يا أحلى حاجة حصلتلي. | نبض واحد 💞, حبيبة قلبي 🔗\"}, \"countdown\": {\"title\": \"THE BIRTHDAY COUNTDOWN • العد التنازلي المنتظر\", \"target_date\": \"2026-06-11T00:00:00+03:00\", \"pending_text\": \"الوقت المتبقي على عيد ميلاد اجمل انسانه في الكون 💖\", \"completed_text\": \"يوم ميلادكِ السعيد بدأ الآن.. جعل الله كل أيامكِ فرحة وسروراً بجانبي ونبضات حبنا لا تنتهي أبداً! 💖✨\", \"completed_title\": \"🎉🎂 كل عام وأنتِ أسعد وأجمل يا سامية! 🎂🎉\"}}','2026-06-15 18:23:25','2026-07-13 19:27:31'),(7,'0001','demo-abdullah','سلمي','عبدالله',1,0,'ar','romantic','neon','{\"hero\": {\"quote\": \"\\\"عامك الجديد وعمري ما يكملوش غير بنور عينيكي وضحكة قلبك الصافية\\\"\", \"kicker\": \"احتفالاً بيوم ميلادك المميز 💖\", \"birthdate\": \"11 • 06 • 2009\", \"avatar_image\": null, \"avatar_title\": \"سامية\", \"banner_image\": \"/assets/images/birthday_banner.png\", \"avatar_subtitle\": \"سامية سر سعادتي وعمري 🌹\"}, \"album\": {\"title\": \"ALBUM OF MEMORIES • ألبوم الذكريات\", \"images\": [\"https://images.unsplash.com/photo-1518199266791-5375a83190b7?auto=format&fit=crop&q=80&w=1200\", \"https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&q=80&w=1200\", \"https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&q=80&w=1200\", \"https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&q=80&w=1200\", \"https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&q=80&w=1200\"], \"description\": \"صور محفورة في القلب، ولحظات لا تُنسى بتفاصيلها الجميلة. اضغطي على أي صورة لرؤيتها بوضوح وحفظها كذكرى مخلدة 🌹\", \"images_text\": \"https://images.unsplash.com/photo-1518199266791-5375a83190b7?auto=format&fit=crop&q=80&w=1200\\nhttps://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&q=80&w=1200\\nhttps://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&q=80&w=1200\\nhttps://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&q=80&w=1200\\nhttps://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&q=80&w=1200\"}, \"audio\": {\"url\": \"https://youtu.be/fJAPs63jZUE?si=VJONXhgbGkNrhtxj\"}, \"basic\": {\"passcode\": \"942026\"}, \"footer\": {\"text\": \"شكراً لمشاركتنا لحظاتكم السعيدة 🌹\", \"whatsapp\": \"201066787955\"}, \"letter\": {\"title\": \"رسالة حب سرية مخصصة لسمسة 💖\", \"description\": \"اضغطي على الختم في المنتصف لفتح الرسالة الخاصة والاستماع للألحان 💌\", \"love_phrase\": \"بحبكككككككككككككك 💗💗💗\", \"letter_title\": \"عيد ميلاد أحلى وأجمل وأطيب 17 في الدنيا كلها.. 🎂✨\", \"letter_content\": \"كل سنة وأنتِ طيبة يا أجمل حاجة حصلتلي في حياتي. النهار ده مش مجرد عيد ميلادك، ده يوم مميز عشان اتولدت فيه أغلى إنسانة في حياتي.\\n\\nكل سنة وأنتِ حبيبتي، وصاحبتي، وبنتي، وأجمل قدر ربنا كتبهولي. كل سنة وأنتِ جنبي، وسندي، وفرحتي. ربنا يديم ضحكتك السكر اللي بموت فيها دي وتفضل تنور أي مكان.\\n\\nربنا يسعد قلبك زي ما بتسعدي قلبي كل يوم. يا رب أفضل طول العمر أشوف الفرحة في عينيكي وأكون سبب في ابتسامتك. نفسي والله كل أعياد ميلادك نحتفل بيها سوا وإحنا بنحقق أحلامنا، وبإذن الله في يوم من الأيام أكون موجود جنبك ونحتفل بيه مع بعض.\"}, \"wishes\": {\"items\": [{\"tags\": [\"حبي الأبدي ✨\", \"حبنا بيكبر ❤️\"], \"text\": \"كل سنة وأنتِ جوة قلبي، كل عام وأنتِ حبي الأول والأخير وروحي وسر ضحكتي وسعادتي يا كل حياتي...\"}, {\"tags\": [\"دنيتي الجميلة 🌱\", \"سند وعمر 🙌\"], \"text\": \"يا رب يباركلي في عمرك يا حبيبتي، ويخلي أيامنا كلها حب وضحكة حلوة وراحة بال على طول سوا.\"}, {\"tags\": [\"عشق ملوش آخر 🌹\", \"نور عيوني 💫\"], \"text\": \"يا نور عيني ويا حتة من روحي، كل سنة وأنتِ طيبة ومعايا وجنبي، ومنورالي حياتي يا أغلى وأجمل ما عندي في الدنيا.\"}, {\"tags\": [\"نبض واحد 💞\", \"حبيبة قلبي 🔗\"], \"text\": \"أنتِ مش بس فرحة يوم ميلادك، أنتِ فرحة العمر كله اللي كنت بتمناها، ربنا يديمك ليا يا أحلى حاجة حصلتلي.\"}], \"title\": \"A PERSONAL WISH • أمنية خاصة\", \"items_text\": \"كل سنة وأنتِ جوة قلبي، كل عام وأنتِ حبي الأول والأخير وروحي وسر ضحكتي وسعادتي يا كل حياتي... | حبي الأبدي ✨, حبنا بيكبر ❤️\\nيا رب يباركلي في عمرك يا حبيبتي، ويخلي أيامنا كلها حب وضحكة حلوة وراحة بال على طول سوا. | دنيتي الجميلة 🌱, سند وعمر 🙌\\nيا نور عيني ويا حتة من روحي، كل سنة وأنتِ طيبة ومعايا وجنبي، ومنورالي حياتي يا أغلى وأجمل ما عندي في الدنيا. | عشق ملوش آخر 🌹, نور عيوني 💫\\nأنتِ مش بس فرحة يوم ميلادك، أنتِ فرحة العمر كله اللي كنت بتمناها، ربنا يديمك ليا يا أحلى حاجة حصلتلي. | نبض واحد 💞, حبيبة قلبي 🔗\"}, \"countdown\": {\"title\": \"THE BIRTHDAY COUNTDOWN • العد التنازلي المنتظر\", \"target_date\": \"2026-06-11T00:00:00+03:00\", \"pending_text\": \"الوقت المتبقي على عيد ميلاد اجمل انسانه في الكون 💖\", \"completed_text\": \"يوم ميلادكِ السعيد بدأ الآن.. جعل الله كل أيامكِ فرحة وسروراً بجانبي ونبضات حبنا لا تنتهي أبداً! 💖✨\", \"completed_title\": \"🎉🎂 كل عام وأنتِ أسعد وأجمل يا سامية! 🎂🎉\"}}','2026-06-15 18:23:25','2026-07-13 19:29:39');
INSERT INTO `birthday_greetings` VALUES (9,'9728','fatima-amro','Fatima','Amro',1,0,'ar','elegant','default','{\"hero\": {\"quote\": \"علي وعد العمر برجاك... علي بعد المسافة اقيف اغازل في حلم لقياك... علي شاطئ المحبه خريف يظلل غيمك انتي هواي\", \"kicker\": \"احتفالاً بيوم ميلادك المميز 💖\", \"birthdate\": \"18 • 06 • 2005\", \"avatar_image\": \"/assets/images/sam.jpeg\", \"avatar_title\": \"سامية\", \"banner_image\": \"/assets/images/birthday_banner.png\", \"avatar_subtitle\": \"فاطمة سر سعادتي وعمري 🌹\"}, \"album\": {\"title\": \"ALBUM OF MEMORIES • ألبوم الذكريات\", \"images\": [\"data:image/jpeg;base64,\", \"data:image/jpeg;base64,\", \"data:image/jpeg;base64,\", \"data:image/jpeg;base64,\", \"data:image/jpeg;base64,\"], \"description\": \"صور محفورة في القلب، ولحظات لا تُنسى بتفاصيلها الجميلة. اضغطي على أي صورة لرؤيتها بوضوح وحفظها كذكرى مخلدة 🌹\", \"images_text\": \"data:image/jpeg;base64,\\ndata:image/jpeg;base64,\\ndata:image/jpeg;base64,\\ndata:image/jpeg;base64,\\ndata:image/jpeg;base64,\"}, \"audio\": {\"url\": \"https://www.youtube.com/watch?v=KuZdBLvIRe0&list=RDKuZdBLvIRe0&start_radio=1\"}, \"basic\": {\"passcode\": \"2072025\"}, \"footer\": {\"text\": \"شكراً لمشاركتنا لحظاتكم السعيدة 🌹\", \"whatsapp\": \"201066787955\"}, \"letter\": {\"title\": \"رسالة حب سرية  💖\", \"description\": \"اضغطي على الختم في المنتصف لفتح الرسالة الخاصة والاستماع للألحان 💌\", \"love_phrase\": \"بحبكككككككككككككك 💗💗💗\", \"letter_title\": \"عيد ميلاد أحلى وأجمل وأطيب 21 سنة في الدنيا كلها.. 🎂✨\", \"letter_content\": \"# ❤️ 18 June ❤️\\n\\n**حبيبتي،**\\n\\nفي ناس بنحبهم لأنهم أسعدونا، وفي ناس بنحبهم لأنهم وقفوا معانا...\\nلكن إنتِ، أنا بحبك لأنك بقيتي جزء من روحي بطريقة ما كنت متخيلها يومًا. 🤍\\n\\nقبل ما أعرفك، كنت فاكر إن الحياة عبارة عن أيام بتعدي وخلاص... دراسة، تعب، نجاحات صغيرة، وخيبات صغيرة.\\n\\nلكن بعدك اكتشفت إن الحياة ممكن تكون **شخص**.\\nشخص واحد بس، وجوده يغيّر طعم الأيام كلها. ✨\\n\\nإنتِ ما أجمل حاجة حصلت لي وبس...\\nإنتِ الحاجة البقت تخليني أتطلع لبكرة.\\n\\nكل مرة أتعب، بلقى نفسي بفكر فيك.\\nوكل مرة أفرح، أول زول عاوز أحكي ليه إنتِ.\\nوكل مرة أخاف من الدنيا، بفتكر إنو فيها إنسانة زيك، فتهون عليّ. 🤍\\n\\n**You are not just someone I love...\\nYou are the place where my heart feels at home. 🏡❤️**\\n\\nعارفة شنو أصعب حاجة؟\\n\\nإنو الكلمات دي كلها، بكل طولها... لسه أقل من الحقيقة.\\n\\nلأن الحقيقة إنك بقيتي:\\n\\n🌷 جزء من دعواتي.\\n🌷 جزء من أحلامي.\\n🌷 وجزء من الصورة البشوف بيها مستقبلي.\\n\\nما بقدر أتخيل سنيني الجاية من غير ما أتخيلك فيها.\\n\\n**If I had to choose one person in every lifetime,\\nin every world,\\nin every version of my story...\\nI would still choose you. ❤️**\\n\\nوفي يوم ميلادك، ما داير أقول ليك:\\n\\n**كل سنة وإنتِ بخير** وبس...\\n\\nداير أقول:\\n\\n**شكرًا. 🤍**\\n\\nشكرًا لأنك جيتي في الزمن المناسب.\\nشكرًا لأنك علمتيني إن الحب ما كلام حلو ساي...\\n\\nالحب طمأنينة.\\n\\nالحب إنك تلقى زول وسط ضجيج الدنيا كلها وتحس إنك وصلت بيتك. 🏡❤️\\n\\nولو سألتيني يومًا:\\n\\n**\\\"إنت بتحبني قدر شنو؟\\\"**\\n\\nيمكن ما أعرف أديك رقم...\\nولا ألقى وصف كفاية...\\n\\nلكن بعرف إنو...\\n\\n**I carry you in every prayer,\\nin every dream,\\nand in every plan I make for the future. ❤️**\\n\\nوبعرف إنو في نهاية كل يوم...\\n\\nبعد كل التعب،\\nوبعد كل الزحمة،\\nوبعد كل الضوضاء...\\n\\nفي اسم واحد بس بقدر يهدّي قلبي...\\n\\n**اسمك. 🤍**\\n\\n---\\n\\n# 🎂 عيد ميلاد سعيد يا حبيبتي ❤️\\n\\nوصدقيني...\\n\\nلو كان عندي ألف حياة،\\nوألف قلب،\\nوألف فرصة أحب...\\n\\n**I would spend every single one of them loving you. ❤️**\\n\\nزينة وعاجباني...\\n\\nوكل ما الأيام تمشي،\\nوكل ما أعرفك أكتر...\\n\\nبكتشف إنو لسه فيك حاجات أجمل ما وصلتها عيني،\\nولا فهمها قلبي كاملة. ✨\\n\\n**Happy Birthday, My Love ❤️**\\n\\nYou are my favorite chapter,\\nmy safest place,\\nand the most beautiful thing that ever happened to me. 🤍✨\"}, \"wishes\": {\"items\": [{\"tags\": [\"حبي الأبدي ✨\", \"حبنا بيكبر ❤️\"], \"text\": \"أقرب حاجة لقلبي ما نبضاتو… إنتِ...\"}, {\"tags\": [\"دنيتي الجميلة 🌱\", \"سند وعمر 🙌\"], \"text\": \"لو الزمن رجّعني ألف مرة، كل مرة حأمشي ليك بنفس الرغبة والمحبة.\"}, {\"tags\": [\"عشق ملوش آخر 🌹\", \"نور عيوني 💫\"], \"text\": \"بحبك المحبة البتخلّي الزول شايل فرحتك قبل فرحتو.\"}, {\"tags\": [\"نبض واحد 💞\", \"حبيبة قلبي 🔗\"], \"text\": \"لقيتك صدفة… وبقيتِ يقيني.\"}, {\"tags\": [\"حبي الأبدي ✨\", \"حبنا بيكبر ❤️\"], \"text\": \"لو كان للعمر معنى، فأجمل معانيه إنتِ...\"}, {\"tags\": [\"دنيتي الجميلة 🌱\", \"سند وعمر 🙌\"], \"text\": \"في ناس بنفتقدهم لو غابوا يوم، لكن إنتِ من الناس البخاف من فكرة غيابهم ذاتها…❤️.\"}], \"title\": \"A PERSONAL WISH • أمنية خاصة\", \"items_text\": \"أقرب حاجة لقلبي ما نبضاتو… إنتِ... | حبي الأبدي ✨, حبنا بيكبر ❤️\\nلو الزمن رجّعني ألف مرة، كل مرة حأمشي ليك بنفس الرغبة والمحبة. | دنيتي الجميلة 🌱, سند وعمر 🙌\\nبحبك المحبة البتخلّي الزول شايل فرحتك قبل فرحتو. | عشق ملوش آخر 🌹, نور عيوني 💫\\nلقيتك صدفة… وبقيتِ يقيني. | نبض واحد 💞, حبيبة قلبي 🔗\\nلو كان للعمر معنى، فأجمل معانيه إنتِ... | حبي الأبدي ✨, حبنا بيكبر ❤️\\nفي ناس بنفتقدهم لو غابوا يوم، لكن إنتِ من الناس البخاف من فكرة غيابهم ذاتها…❤️. | دنيتي الجميلة 🌱, سند وعمر 🙌\"}, \"countdown\": {\"title\": \"THE BIRTHDAY COUNTDOWN • العد التنازلي المنتظر\", \"target_date\": \"2026-06-18T00:00:00+03:00\", \"pending_text\": \"الوقت المتبقي على عيد ميلاد اجمل انسانه في الكون 💖\", \"completed_text\": \"يوم ميلادكِ السعيد بدأ الآن.. جعل الله كل أيامكِ فرحة وسروراً بجانبي ونبضات حبنا لا تنتهي أبداً! 💖✨\", \"completed_title\": \"🎉🎂 كل عام وأنتِ أسعد وأجمل يا فاطمة! 🎂🎉\"}}','2026-06-16 12:29:29','2026-06-16 18:45:11');
INSERT INTO `birthday_greetings` VALUES (13,'0009','laila-omar','ليلي','عمر',1,1,'ar','romantic','default','{\"hero\": {\"quote\": \"\\\"عامك الجديد وعمري ما يكملوش غير بنور عينيكي وضحكة قلبك الصافية\\\"\", \"kicker\": \"احتفالاً بيوم ميلادك المميز 💖\", \"birthdate\": \"11 • 06 • 2009\", \"avatar_image\": null, \"avatar_title\": \"سامية\", \"banner_image\": \"/assets/images/birthday_banner.png\", \"avatar_subtitle\": \"سامية سر سعادتي وعمري 🌹\"}, \"album\": {\"title\": \"ALBUM OF MEMORIES • ألبوم الذكريات\", \"images\": [\"https://images.unsplash.com/photo-1518199266791-5375a83190b7?auto=format&fit=crop&q=80&w=1200\", \"https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&q=80&w=1200\", \"https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&q=80&w=1200\", \"https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&q=80&w=1200\", \"https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&q=80&w=1200\"], \"description\": \"صور محفورة في القلب، ولحظات لا تُنسى بتفاصيلها الجميلة. اضغطي على أي صورة لرؤيتها بوضوح وحفظها كذكرى مخلدة 🌹\", \"images_text\": \"https://images.unsplash.com/photo-1518199266791-5375a83190b7?auto=format&fit=crop&q=80&w=1200\\nhttps://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&q=80&w=1200\\nhttps://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&q=80&w=1200\\nhttps://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&q=80&w=1200\\nhttps://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&q=80&w=1200\"}, \"audio\": {\"url\": \"https://youtu.be/fJAPs63jZUE?si=VJONXhgbGkNrhtxj\"}, \"basic\": {\"passcode\": \"942026\"}, \"footer\": {\"text\": \"شكراً لمشاركتنا لحظاتكم السعيدة 🌹\", \"whatsapp\": \"201066787955\"}, \"letter\": {\"title\": \"رسالة حب سرية مخصصة لسمسة 💖\", \"description\": \"اضغطي على الختم في المنتصف لفتح الرسالة الخاصة والاستماع للألحان 💌\", \"love_phrase\": \"بحبكككككككككككككك 💗💗💗\", \"letter_title\": \"عيد ميلاد أحلى وأجمل وأطيب 17 في الدنيا كلها.. 🎂✨\", \"letter_content\": \"كل سنة وأنتِ طيبة يا أجمل حاجة حصلتلي في حياتي. النهار ده مش مجرد عيد ميلادك، ده يوم مميز عشان اتولدت فيه أغلى إنسانة في حياتي.\\n\\nكل سنة وأنتِ حبيبتي، وصاحبتي، وبنتي، وأجمل قدر ربنا كتبهولي. كل سنة وأنتِ جنبي، وسندي، وفرحتي. ربنا يديم ضحكتك السكر اللي بموت فيها دي وتفضل تنور أي مكان.\\n\\nربنا يسعد قلبك زي ما بتسعدي قلبي كل يوم. يا رب أفضل طول العمر أشوف الفرحة في عينيكي وأكون سبب في ابتسامتك. نفسي والله كل أعياد ميلادك نحتفل بيها سوا وإحنا بنحقق أحلامنا، وبإذن الله في يوم من الأيام أكون موجود جنبك ونحتفل بيه مع بعض.\"}, \"wishes\": {\"items\": [{\"tags\": [\"حبي الأبدي ✨\", \"حبنا بيكبر ❤️\"], \"text\": \"كل سنة وأنتِ جوة قلبي، كل عام وأنتِ حبي الأول والأخير وروحي وسر ضحكتي وسعادتي يا كل حياتي...\"}, {\"tags\": [\"دنيتي الجميلة 🌱\", \"سند وعمر 🙌\"], \"text\": \"يا رب يباركلي في عمرك يا حبيبتي، ويخلي أيامنا كلها حب وضحكة حلوة وراحة بال على طول سوا.\"}, {\"tags\": [\"عشق ملوش آخر 🌹\", \"نور عيوني 💫\"], \"text\": \"يا نور عيني ويا حتة من روحي، كل سنة وأنتِ طيبة ومعايا وجنبي، ومنورالي حياتي يا أغلى وأجمل ما عندي في الدنيا.\"}, {\"tags\": [\"نبض واحد 💞\", \"حبيبة قلبي 🔗\"], \"text\": \"أنتِ مش بس فرحة يوم ميلادك، أنتِ فرحة العمر كله اللي كنت بتمناها، ربنا يديمك ليا يا أحلى حاجة حصلتلي.\"}], \"title\": \"A PERSONAL WISH • أمنية خاصة\", \"items_text\": \"كل سنة وأنتِ جوة قلبي، كل عام وأنتِ حبي الأول والأخير وروحي وسر ضحكتي وسعادتي يا كل حياتي... | حبي الأبدي ✨, حبنا بيكبر ❤️\\nيا رب يباركلي في عمرك يا حبيبتي، ويخلي أيامنا كلها حب وضحكة حلوة وراحة بال على طول سوا. | دنيتي الجميلة 🌱, سند وعمر 🙌\\nيا نور عيني ويا حتة من روحي، كل سنة وأنتِ طيبة ومعايا وجنبي، ومنورالي حياتي يا أغلى وأجمل ما عندي في الدنيا. | عشق ملوش آخر 🌹, نور عيوني 💫\\nأنتِ مش بس فرحة يوم ميلادك، أنتِ فرحة العمر كله اللي كنت بتمناها، ربنا يديمك ليا يا أحلى حاجة حصلتلي. | نبض واحد 💞, حبيبة قلبي 🔗\"}, \"countdown\": {\"title\": \"THE BIRTHDAY COUNTDOWN • العد التنازلي المنتظر\", \"target_date\": \"2026-06-11T00:00:00+03:00\", \"pending_text\": \"الوقت المتبقي على عيد ميلاد اجمل انسانه في الكون 💖\", \"completed_text\": \"يوم ميلادكِ السعيد بدأ الآن.. جعل الله كل أيامكِ فرحة وسروراً بجانبي ونبضات حبنا لا تنتهي أبداً! 💖✨\", \"completed_title\": \"🎉🎂 كل عام وأنتِ أسعد وأجمل يا سامية! 🎂🎉\"}}','2026-06-20 17:05:46','2026-07-13 19:27:12'),(14,'1623','roaa-meratamo','رؤي','مرات عموو',1,0,'ar','modern','romantic','{\"hero\": {\"quote\": \"\\\"يا رب تكون كل أيامك فرحة،\\nوتكبري وتحققي كل اللي نفسك فيه،\\nوكل سنة وإنتِ أحلى وأشطر بنوتة. 🎀✨\\\"\", \"kicker\": \"احتفال بعيد ميلاد أحلى بنوتة في الدنيا 🎉\", \"birthdate\": \"17 • 07 • 2016\", \"avatar_image\": null, \"avatar_title\": \"سامية\", \"banner_image\": \"/assets/images/birthday_banner.png\", \"avatar_subtitle\": \"أميرة العيلة الصغيرة 👑💖\"}, \"album\": {\"title\": \"•  أجمل لحظات رؤى🎀\", \"images\": [\"http://localhost/storage/invitations/gallery/GHplLkDvNBMUkbmOjLW2uacr3n8y6hbG0P7482o5.jpg\", \"http://localhost/storage/invitations/gallery/kSfKENaAcr0CupBtD8c7sNNfPLszD3nl5jqvRGGe.jpg\", \"http://localhost/storage/invitations/gallery/WAcKV56F6QWU8BrflQ5fdZHWS51uqv23hddioDnB.jpg\", \"http://localhost/storage/invitations/gallery/LGwaLcvDHacekOa8Cuxta3sAlyJ4loPGyMrMBfoI.jpg\", \"http://localhost/storage/invitations/gallery/sHRVPTRRyRQ3udSqoVN5e7xCU01Pw8cNuxwmjbUD.jpg\"], \"description\": \"🎈 لحظات مليانة ضحك وفرحة وبراءة.\\nكل صورة بتحكي قصة جميلة من ذكريات رؤى، احتفظنا بيها علشان تفضل منورة قلوبنا. 🌷\", \"images_text\": \"http://localhost/storage/invitations/gallery/GHplLkDvNBMUkbmOjLW2uacr3n8y6hbG0P7482o5.jpg\\nhttp://localhost/storage/invitations/gallery/kSfKENaAcr0CupBtD8c7sNNfPLszD3nl5jqvRGGe.jpg\\nhttp://localhost/storage/invitations/gallery/WAcKV56F6QWU8BrflQ5fdZHWS51uqv23hddioDnB.jpg\\nhttp://localhost/storage/invitations/gallery/LGwaLcvDHacekOa8Cuxta3sAlyJ4loPGyMrMBfoI.jpg\\nhttp://localhost/storage/invitations/gallery/sHRVPTRRyRQ3udSqoVN5e7xCU01Pw8cNuxwmjbUD.jpg\"}, \"audio\": {\"url\": \"https://youtu.be/G6qwnMQXiII?si=nD68r0qKTG4VOLzM\"}, \"basic\": {\"passcode\": \"1772016\"}, \"footer\": {\"text\": \"شكراً لمشاركتنا لحظاتكم السعيدة 🌹\", \"whatsapp\": \"201557517718\"}, \"letter\": {\"title\": \"رسالة خاصة لرؤى 💌\", \"description\": \"اضغطي على الظرف لفتح رسالة صغيرة مكتوبة بكل الحب من مرات عمك.💖\", \"love_phrase\": \"اللهم إنها رؤي !  وطفلتي المدللة  يارب اجعل مستقبلها أجمل مما نريد...  وأسعدنا برؤيتها تكبر كل يوم وهي في أفضل حال  بنتي وحبيبتي اللهم إنا نستودعك حياتها وصحتها وعافيتها  حفظك الله ورعاك\", \"letter_title\": \"عيد ميلاد أحلى وأجمل وأطيب 17 في الدنيا كلها.. 🎂✨\", \"letter_content\": \"كل سنة وأنت طيبة يا أجمل حاجة حصلتلي في حياتي. النهار ده مش مجرد عيد ميلادك، وه يوم مميز عشان اتولدت فيه أغلى إنسانة في حياتي.\\n\\nكل سنة وأنت حبيبتي، وصاحبتي، وبنتي، وأجمل قدر ربنا كتبهولي. كل سنة وأنتِ جنبي، وسندي، وفرحتي. ربنا يديم ضحكتك السكر اللي بموت فيها دي وتفضل تنور أي مكان.\\n\\nربنا يسعد قلبك زي ما بتسعدي قلبي كل يوم. يا رب أفضل طول العمر أشوف الفرحة في عينيكي وأكون سبب في ابتسامتك. نفسي والله كل أعياد ميلادك نحتفل بيها سوا واحنا بنحقق أحلامنا، وبإذن الله في يوم من الأيام أكون موجود جنبك و نحتفل بيه مع بعض\"}, \"wishes\": {\"items\": [{\"tags\": [\"من مرات عمك\", \"حب\"], \"text\": \"💖 كل سنة وإنتِ طيبة يا سامية، ربنا يحفظك ويخليكي دايمًا سعيدة.\"}, {\"tags\": [\"أمنيات\", \"عيد ميلاد\"], \"text\": \"🎂 بتمنالك سنة مليانة نجاح وضحك ولعب وهدايا كتير.\"}, {\"tags\": [\"نجاح\", \"تفوق\"], \"text\": \"🌸 يا رب أشوفك كل سنة أحلى وأشطر وأطيب بنوتة.\"}, {\"tags\": [\"سعادة\", \"ابتسامة\"], \"text\": \"🎈 وجودك بيفرح كل اللي حواليكي، خليكي دايمًا مبتسمة.\"}, {\"tags\": [\"أحلام\", \"هدايا\"], \"text\": \"🎁 عيد ميلاد سعيد يا حبيبتي، وإن شاء الله كل أحلامك تتحقق.\"}], \"title\": \"• أمنية خاصة\", \"items_text\": \"💖 كل سنة وإنتِ طيبة يا سامية، ربنا يحفظك ويخليكي دايمًا سعيدة. | من مرات عمك, حب\\n🎂 بتمنالك سنة مليانة نجاح وضحك ولعب وهدايا كتير. | أمنيات, عيد ميلاد\\n🌸 يا رب أشوفك كل سنة أحلى وأشطر وأطيب بنوتة. | نجاح, تفوق\\n🎈 وجودك بيفرح كل اللي حواليكي، خليكي دايمًا مبتسمة. | سعادة, ابتسامة\\n🎁 عيد ميلاد سعيد يا حبيبتي، وإن شاء الله كل أحلامك تتحقق. | أحلام, هدايا\"}, \"countdown\": {\"title\": \"🎉 العد التنازلي لعيد الميلاد\", \"target_date\": \"2026-07-17T00:00:00+03:00\", \"pending_text\": \"🎀🎂 باقي شوية على يوم فرحتك الكبير يا أحلى بنوتة! ⏳\", \"completed_text\": \"🎂💖 كل سنة وإنتِ طيبة يا رؤي.\\nربنا يحفظك ويخليكي دايمًا سعيدة ومتفوقة، ويملأ أيامك بالفرحة واللعب والنجاح.\\nبتمنالك عيد ميلاد مليان مفاجآت جميلة وضحك وهدايا.\\nبحبك جدًا يا حبيبتي. 🎁🎈\", \"completed_title\": \"🎈🎁 النهارده عيد ميلادك يا رؤي ! كل سنة وإنتِ سعيدة 🎂💖\"}}','2026-07-06 16:42:21','2026-07-10 22:57:39'),(15,'5598','niera-amen-sara-salah','Niera Amen','Sara salah',1,0,'ar','elegant','romantic','{\"hero\": {\"quote\": \"\\\"عامك الجديد وعمري ما يكملوش غير بنور عينيكي وضحكة قلبك الصافية\\\"\", \"kicker\": \"احتفالاً بيوم ميلادك المميز 💖\", \"birthdate\": \"17• 07 • 1999\", \"avatar_image\": null, \"avatar_title\": \"سامية\", \"banner_image\": \"/assets/images/birthday_banner.png\", \"avatar_subtitle\": \"اجمل من يتم ال27🌹\"}, \"album\": {\"title\": \"ALBUM OF MEMORIES • ألبوم الذكريات\", \"images\": [\"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/QnKag5ESu4Es1Tj0GdDXlhoMAGlc7a3KHhdyfkQl.jpg\", \"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/XPPFJeFVo7ZPm4J8Blk2EZCAqjxHnbUBpwuJJyRl.jpg\", \"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/aLoQrdeaTqcr0TrYny3PmYQAXZxpfD0rV3J0tXGa.jpg\", \"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/gEspiGIvfDtCieXqsEGco5CkNmpLJRzpg62VbIsq.jpg\", \"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/4bFyB2eGohWSHaD6NDwbMlUxnGkTmU3ph0WRN7QS.jpg\", \"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/GceQKqXSo93L6IBdHuAEHgLuljkpoVbwIkk4x6D0.jpg\"], \"description\": \"صور محفورة في القلب، ولحظات لا تُنسى بتفاصيلها الجميلة. اضغطي على أي صورة لرؤيتها بوضوح وحفظها كذكرى مخلدة 🌹\", \"images_text\": \"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/QnKag5ESu4Es1Tj0GdDXlhoMAGlc7a3KHhdyfkQl.jpg\\nhttps://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/XPPFJeFVo7ZPm4J8Blk2EZCAqjxHnbUBpwuJJyRl.jpg\\nhttps://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/aLoQrdeaTqcr0TrYny3PmYQAXZxpfD0rV3J0tXGa.jpg\\nhttps://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/gEspiGIvfDtCieXqsEGco5CkNmpLJRzpg62VbIsq.jpg\\nhttps://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/4bFyB2eGohWSHaD6NDwbMlUxnGkTmU3ph0WRN7QS.jpg\\nhttps://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/GceQKqXSo93L6IBdHuAEHgLuljkpoVbwIkk4x6D0.jpg\"}, \"audio\": {\"url\": \"https://youtu.be/wNut8QshEx0?si=QyxBktp-XTOiqE_X\"}, \"basic\": {\"passcode\": \"1771999\"}, \"footer\": {\"text\": \"شكراً لمشاركتنا لحظاتكم السعيدة 🌹\", \"whatsapp\": \"201557517718\"}, \"letter\": {\"title\": \"رسالة حب سرية مخصصة لنيرة 💖\", \"description\": \"اضغطي على الختم في المنتصف لفتح الرسالة الخاصة والاستماع للألحان 💌\", \"love_phrase\": \"بحبكككككككككككككك 💗💗💗\", \"letter_title\": \"عيد ميلاد أحلى وأجمل وأطيب 27في الدنيا كلها.. 🎂✨\", \"letter_content\": \"كل سنة وأنتِ طيبة يا نيره، يا أجمل صاحبة دخلت حياتي. النهارده مش مجرد عيد ميلادك، ده يوم مميز جدًا، لأنه اليوم اللي اتولدت فيه إنسانة وجودها فرق معايا بجد وخلى أيامي أحلى.\\n\\nكل سنة وأنتِ صاحبتي، وأختي اللي الحياة رزقتني بيها، وسندي في كل وقت، وأجمل حد أقدر أحكيله كل حاجة من غير خوف. ربنا يديم ضحكتك الحلوة اللي بتنور الدنيا، ويفضل قلبك مليان راحة وفرحة زي ما هو دايمًا.\\n\\nربنا يسعد قلبك ويحققلك كل اللي نفسك فيه، ويفتحلك كل أبواب الخير، ويبعد عنك أي حزن أو تعب. تستحقي كل حاجة حلوة في الدنيا، وأتمنى أشوفك دايمًا ناجحة ومبسوطة وفخورة بنفسك.\\n\\nأنا ممتنة جدًا إنك في حياتي، وربنا يديم صداقتنا سنين طويلة مليانة ذكريات حلوة وضحك ومواقف نفتكرها ونضحك عليها. وإن شاء الله نفضل نحتفل بعيد ميلادك كل سنة سوا، ونشوف أحلامنا وهي بتتحقق واحدة واحدة.\\n\\nكل سنة وأنتِ بخير يا نيره، وربنا يحفظك ليا ويديم وجودك في حياتي. بحبك جدًا يا أحلى صاحبة. 🤍🎂\"}, \"wishes\": {\"items\": [{\"tags\": [\"صاحبتي العمر 💖\", \"أحلى نعمة ✨\"], \"text\": \"كل سنة وأنتِ أجمل صاحبة وأغلى إنسانة في حياتي، كل سنة وأنتِ سبب الضحكة الحلوة والذكريات اللي عمرها ما بتتنسي يا نيره...\"}, {\"tags\": [\"ربنا يحفظك 🌸\", \"صداقة للأبد 🤍\"], \"text\": \"يا رب يباركلك في عمرك يا نيره، ويحققلك كل اللي بتتمنيه، وتفضلي دايمًا ناجحة وفرحانة ومليانة طاقة وحب، وربنا يديم صداقتنا لأجمل سنين كتير.\"}, {\"tags\": [\"فرحة قلبي 🌷\", \"أجمل صاحبة 💫\"], \"text\": \"يا أجمل صاحبة وأطيب قلب، كل سنة وأنتِ بخير وسعيدة، ومنورة الدنيا كلها بابتسامتك، ويا رب أشوفك دايمًا في أعلى الأماكن وتحققي كل أحلامك.\"}, {\"tags\": [\"أخت من غير دم 💞\", \"ربنا يديمك 🌼\"], \"text\": \"أنتِ مش بس صاحبتي، أنتِ الأخت اللي الحياة هدتني إياها، والونس في كل وقت، ربنا يديم وجودك في حياتي، وكل سنة وأنتِ بخير يا نيره.\"}], \"title\": \"A PERSONAL WISH • أمنية خاصة\", \"items_text\": \"كل سنة وأنتِ أجمل صاحبة وأغلى إنسانة في حياتي، كل سنة وأنتِ سبب الضحكة الحلوة والذكريات اللي عمرها ما بتتنسي يا نيره... | صاحبتي العمر 💖, أحلى نعمة ✨\\nيا رب يباركلك في عمرك يا نيره، ويحققلك كل اللي بتتمنيه، وتفضلي دايمًا ناجحة وفرحانة ومليانة طاقة وحب، وربنا يديم صداقتنا لأجمل سنين كتير. | ربنا يحفظك 🌸, صداقة للأبد 🤍\\nيا أجمل صاحبة وأطيب قلب، كل سنة وأنتِ بخير وسعيدة، ومنورة الدنيا كلها بابتسامتك، ويا رب أشوفك دايمًا في أعلى الأماكن وتحققي كل أحلامك. | فرحة قلبي 🌷, أجمل صاحبة 💫\\nأنتِ مش بس صاحبتي، أنتِ الأخت اللي الحياة هدتني إياها، والونس في كل وقت، ربنا يديم وجودك في حياتي، وكل سنة وأنتِ بخير يا نيره. | أخت من غير دم 💞, ربنا يديمك 🌼\"}, \"countdown\": {\"title\": \"THE BIRTHDAY COUNTDOWN • العد التنازلي المنتظر\", \"target_date\": \"2026-07-17T00:00:00+03:00\", \"pending_text\": \"الوقت المتبقي على عيد ميلاد اجمل نيرة في الكون 💖\", \"completed_text\": \"يوم ميلادكِ السعيد بدأ الآن.. جعل الله كل أيامكِ فرحة وسروراً بجانبي ونبضات حبنا لا تنتهي أبداً! 💖✨\", \"completed_title\": \"🎉🎂 كل عام وأنتِ أسعد وأجمل يا نيرة! 🎂🎉\"}}','2026-07-17 12:48:06','2026-07-17 13:00:31'),(16,'3679','recipient-sender','مني','عبدالله',1,0,'en','elegant','default','{\"hero\": {\"quote\": \"\\\"Your new year and my life are incomplete without the light of your eyes and the laughter of your pure heart.\\\"\", \"kicker\": \"Celebrating Your Special Day 💖\", \"birthdate\": \"11 • 06 • 2009\", \"avatar_image\": null, \"avatar_title\": \"Sweetheart\", \"banner_image\": \"/assets/images/birthday_banner.png\", \"avatar_subtitle\": \"The secret to my happiness and life 🌹\"}, \"album\": {\"title\": \"ALBUM OF MEMORIES • Our Beautiful Moments\", \"images\": [], \"description\": \"Photos carved in the heart, and unforgettable moments with beautiful details. Click any photo to zoom in 🌹\", \"images_text\": null}, \"audio\": {\"url\": null}, \"basic\": {\"passcode\": \"942026\"}, \"footer\": {\"text\": \"Thank you for sharing your happy moments with us 🌹\", \"whatsapp\": \"201066787955\"}, \"letter\": {\"title\": \"A Secret Love Letter Dedicated to You 💖\", \"description\": \"Click the seal in the middle to open the private letter and listen to the music 💌\", \"love_phrase\": \"I love you so much 💗💗💗\", \"letter_title\": \"Happy Birthday to the most beautiful person in the world.. 🎂✨\", \"letter_content\": \"Happy Birthday to the best thing that ever happened to me in my life. Today is not just your birthday, it is a special day because the most precious person in my life was born.\\n\\nHappy Birthday, my love, my friend, my daughter, and the most beautiful destiny God wrote for me. Happy Birthday to you beside me, my support, and my joy.\\n\\nMay God make your heart happy just as you make my heart happy every day. I hope to spend my whole life seeing the joy in your eyes and being the reason for your smile. I hope we celebrate all your birthdays together achieving our dreams.\"}, \"wishes\": {\"items\": [{\"tags\": [\"Forever Love ✨\", \"Growing Together ❤️\"], \"text\": \"Happy Birthday to the one who makes my world complete. May your year be filled with love and joy!\"}, {\"tags\": [\"My Beautiful World 🌱\", \"My Support & Companion 🙌\"], \"text\": \"Wishing you a lifetime of laughter, shared dreams, and endless happiness by my side.\"}, {\"tags\": [\"Endless Love 🌹\", \"Light of My Eyes 💫\"], \"text\": \"You are the light of my life and the joy in my heart. Happy Birthday, my dearest one.\"}, {\"tags\": [\"One Beat 💞\", \"Heart and Soul 🔗\"], \"text\": \"You are not just a blessing for today, but for a lifetime. Happy Birthday to my favorite person.\"}], \"title\": \"A PERSONAL WISH • A Special Dedication\", \"items_text\": \"Happy Birthday to the one who makes my world complete. May your year be filled with love and joy! | Forever Love ✨, Growing Together ❤️\\nWishing you a lifetime of laughter, shared dreams, and endless happiness by my side. | My Beautiful World 🌱, My Support & Companion 🙌\\nYou are the light of my life and the joy in my heart. Happy Birthday, my dearest one. | Endless Love 🌹, Light of My Eyes 💫\\nYou are not just a blessing for today, but for a lifetime. Happy Birthday to my favorite person. | One Beat 💞, Heart and Soul 🔗\"}, \"countdown\": {\"title\": \"THE BIRTHDAY COUNTDOWN • The Awaited Moment\", \"target_date\": \"2026-06-11T00:00:00+03:00\", \"pending_text\": \"Time remaining until the birthday of the most beautiful person in the universe 💖\", \"completed_text\": \"Your happy birthday has started now.. May all your days be filled with joy by my side! 💖✨\", \"completed_title\": \"🎉🎂 Happy Birthday, My Love! 🎂🎉\"}}','2026-07-17 12:53:17','2026-07-17 12:53:17'),(17,'0429','heba-mohamed','هبه','محمد',1,0,'ar','modern','neon','{\"hero\": {\"quote\": \"\\\"عامك الجديد وعمري ما يكملوش غير بنور عينيكي وضحكة قلبك الصافية\\\"\", \"kicker\": \"احتفالاً بيوم ميلادك المميز 💖\", \"birthdate\": \"22 • 07 • 1995\", \"avatar_image\": null, \"avatar_title\": \"سامية\", \"banner_image\": \"/assets/images/birthday_banner.png\", \"avatar_subtitle\": \"هبه سر سعادتي وعمري 🌹\"}, \"album\": {\"title\": \"• ألبوم الذكريات\", \"images\": [\"http://localhost/storage/invitations/gallery/PMDW64YrxEPqpOETNJMpUe2RiE0qcGBQsg7eeWt9.webp\", \"http://localhost/storage/invitations/gallery/5T6S562EIz1T3l1H9CqNWWTs30oXC6sdzP0uTDuA.jpg\", \"http://localhost/storage/invitations/gallery/CUdeur2EZNrvXvEyYHbWKwj82aYNh8JTKdCOKHF1.jpg\", \"http://localhost/storage/invitations/gallery/7DHQ2iPPKkCrdm1zDctK7XwZmgEIXrKHmKAA5ZoT.jpg\"], \"description\": \"صور محفورة في القلب، ولحظات لا تُنسى بتفاصيلها الجميلة. اضغطي على أي صورة لرؤيتها بوضوح وحفظها كذكرى مخلدة 🌹\", \"images_text\": \"http://localhost/storage/invitations/gallery/PMDW64YrxEPqpOETNJMpUe2RiE0qcGBQsg7eeWt9.webp\\nhttp://localhost/storage/invitations/gallery/5T6S562EIz1T3l1H9CqNWWTs30oXC6sdzP0uTDuA.jpg\\nhttp://localhost/storage/invitations/gallery/CUdeur2EZNrvXvEyYHbWKwj82aYNh8JTKdCOKHF1.jpg\\nhttp://localhost/storage/invitations/gallery/7DHQ2iPPKkCrdm1zDctK7XwZmgEIXrKHmKAA5ZoT.jpg\"}, \"audio\": {\"url\": \"https://youtu.be/mdnk9M7VYso?si=FuoQghwwjacDr5nb\"}, \"basic\": {\"passcode\": \"2271995\"}, \"footer\": {\"text\": \"شكراً لمشاركتنا لحظاتكم السعيدة 🌹\", \"whatsapp\": \"201557517718\"}, \"letter\": {\"title\": \"رسالة حب سرية مخصصة لهبه 💖\", \"description\": \"اضغطي على الختم في المنتصف لفتح الرسالة الخاصة والاستماع للألحان 💌\", \"love_phrase\": \"انت فصلي المفضل❤️❤️\", \"letter_title\": \"عيد ميلاد أحلى وأجمل وأطيب واحده في الدنيا كلها.. 🎂✨\", \"letter_content\": \"كل سنة وإنتِ طيبة يا **هبة**، يا أجمل نعمة وأغلى هدية ربنا رزقني بيها. 🤍\\n\\nالنهارده مش مجرد عيد ميلاد، ده اليوم اللي اتولدت فيه أغلى إنسانة في حياتي، واليوم اللي الدنيا بقت فيه أجمل بوجودك.\\n\\nكل سنة وإنتِ حبيبتي، وصاحبتي، وسندي، وأجمل قدر ربنا كتبهولي. كل سنة وإنتِ منورة حياتي بابتسامتك اللي بعشقها، وبقلبك الطيب اللي بيهون عليا أي حاجة.\\n\\nربنا يديم ضحكتك، ويحفظك من كل شر، ويحققلك كل اللي نفسك فيه، ويسعد قلبك قد ما إنتِ بتسعدي قلبي كل يوم.\\n\\nوأتمنى من كل قلبي إن كل أعياد ميلادك الجاية نكون بنحتفل بيها سوا، وإحنا بنحقق أحلامنا، وبنبني حياتنا مع بعض. وجودك في حياتي أكبر نعمة، وهفضل طول عمري أحمد ربنا عليها.\\n\\n**كل سنة وإنتِ أجمل حاجة في حياتي يا هبة، وكل سنة وإنتِ بخير، وعقبال 100 سنة كلها سعادة، وصحة، وضحكة ما تفارقش وشك أبدًا. ❤️🎂**\"}, \"wishes\": {\"items\": [{\"tags\": [\"حبي الأبدي ✨\", \"حبنا بيكبر ❤️\"], \"text\": \"كل سنة وأنتِ جوة قلبي، كل عام وأنتِ حبي الأول والأخير وروحي وسر ضحكتي وسعادتي يا كل حياتي...\"}, {\"tags\": [\"دنيتي الجميلة 🌱\", \"سند وعمر 🙌\"], \"text\": \"يا رب يباركلي في عمرك يا حبيبتي، ويخلي أيامنا كلها حب وضحكة حلوة وراحة بال على طول سوا.\"}, {\"tags\": [\"عشق ملوش آخر 🌹\", \"نور عيوني 💫\"], \"text\": \"يا نور عيني ويا حتة من روحي، كل سنة وأنتِ طيبة ومعايا وجنبي، ومنورالي حياتي يا أغلى وأجمل ما عندي في الدنيا.\"}, {\"tags\": [\"نبض واحد 💞\", \"حبيبة قلبي 🔗\"], \"text\": \"أنتِ مش بس فرحة يوم ميلادك، أنتِ فرحة العمر كله اللي كنت بتمناها، ربنا يديمك ليا يا أحلى حاجة حصلتلي.\"}], \"title\": \"• أمنية خاصة\", \"items_text\": \"كل سنة وأنتِ جوة قلبي، كل عام وأنتِ حبي الأول والأخير وروحي وسر ضحكتي وسعادتي يا كل حياتي... | حبي الأبدي ✨, حبنا بيكبر ❤️\\nيا رب يباركلي في عمرك يا حبيبتي، ويخلي أيامنا كلها حب وضحكة حلوة وراحة بال على طول سوا. | دنيتي الجميلة 🌱, سند وعمر 🙌\\nيا نور عيني ويا حتة من روحي، كل سنة وأنتِ طيبة ومعايا وجنبي، ومنورالي حياتي يا أغلى وأجمل ما عندي في الدنيا. | عشق ملوش آخر 🌹, نور عيوني 💫\\nأنتِ مش بس فرحة يوم ميلادك، أنتِ فرحة العمر كله اللي كنت بتمناها، ربنا يديمك ليا يا أحلى حاجة حصلتلي. | نبض واحد 💞, حبيبة قلبي 🔗\"}, \"countdown\": {\"title\": \"• العد التنازلي المنتظر\", \"target_date\": \"1995-07-22T00:00:00+03:00\", \"pending_text\": \"الوقت المتبقي على عيد ميلاد اجمل انسانه في الكون 💖\", \"completed_text\": \"يوم ميلادكِ السعيد بدأ الآن.. جعل الله كل أيامكِ فرحة وسروراً بجانبي ونبضات حبنا لا تنتهي أبداً! 💖✨\", \"completed_title\": \"🎉🎂 كل عام وأنتِ أسعد وأجمل يا هبه! 🎂🎉\"}}','2026-07-18 22:34:36','2026-07-18 22:34:36'),(18,'0210','basbosa-mahmoud','بسبوستي','محمود',0,0,'ar','classic','romantic','{\"hero\": {\"quote\": \"\\\"عامك الجديد وعمري ما يكملوش غير بنور عينيكي وضحكة قلبك الصافية\\\"\", \"kicker\": \"احتفالاً بيوم ميلادك المميز 💖\", \"birthdate\": \"30 • 07 • 2007\", \"avatar_image\": null, \"avatar_title\": \"سامية\", \"banner_image\": \"/assets/images/birthday_banner.png\", \"avatar_subtitle\": \"بسبوسه سر سعادتي وعمري 🌹\"}, \"album\": {\"title\": \"• ألبوم الذكريات\", \"images\": [\"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/JY9COigJqWoAkmInLkhezgohDhmv8zP0U5dzKluZ.jpg\", \"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/Kz7vbJKUAFwqLFiilyen5tmNaiAKaFmZm3Tkx1O7.jpg\", \"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/GqyUu18apDzS7qAbnkBpODXTfRgAwZ2u63QMSo72.jpg\", \"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/XK9kBDoojgAHoAMn6tFTqx28WkyFjbm9EAsSGbQq.jpg\", \"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/vdq3xpgOnIBMCH9NMe5qVCBzW4wUvJwUx97lVAjA.jpg\", \"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/QfMVZNfFsoQbhOWaUkETyCFiO28sQMaUdNPMWPKe.jpg\", \"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/FLAPruLUgr4tCdHrNYasOAymvGFk7jsenCDlZbIs.jpg\", \"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/nb7zCUm0EDTPrNHK6q2DEcIgCD0CLMKfC1vwJ9rC.jpg\", \"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/iQZns3Ksb4qxrbSP9qtIQkFtCzqZb05Pe8qI64kz.jpg\"], \"description\": \"صور محفورة في القلب، ولحظات لا تُنسى بتفاصيلها الجميلة. اضغطي على أي صورة لرؤيتها بوضوح وحفظها كذكرى مخلدة 🌹\", \"images_text\": \"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/JY9COigJqWoAkmInLkhezgohDhmv8zP0U5dzKluZ.jpg\\nhttps://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/Kz7vbJKUAFwqLFiilyen5tmNaiAKaFmZm3Tkx1O7.jpg\\nhttps://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/GqyUu18apDzS7qAbnkBpODXTfRgAwZ2u63QMSo72.jpg\\nhttps://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/XK9kBDoojgAHoAMn6tFTqx28WkyFjbm9EAsSGbQq.jpg\\nhttps://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/vdq3xpgOnIBMCH9NMe5qVCBzW4wUvJwUx97lVAjA.jpg\\nhttps://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/QfMVZNfFsoQbhOWaUkETyCFiO28sQMaUdNPMWPKe.jpg\\nhttps://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/FLAPruLUgr4tCdHrNYasOAymvGFk7jsenCDlZbIs.jpg\\nhttps://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/nb7zCUm0EDTPrNHK6q2DEcIgCD0CLMKfC1vwJ9rC.jpg\\nhttps://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/iQZns3Ksb4qxrbSP9qtIQkFtCzqZb05Pe8qI64kz.jpg\"}, \"audio\": {\"url\": \"https://youtu.be/Pan1Fbez0jE?si=A5gVQ58x0Vyp1qFZ\"}, \"basic\": {\"passcode\": \"1622026\"}, \"footer\": {\"text\": \"شكراً لمشاركتنا لحظاتكم السعيدة 🌹\", \"whatsapp\": null}, \"letter\": {\"title\": \"رسالة حب سرية مخصصة لبسبوسه💖\", \"description\": \"اضغطي على الختم في المنتصف لفتح الرسالة الخاصة والاستماع للألحان 💌\", \"love_phrase\": \"فصلي المفضل 💗💗💗\", \"letter_title\": \"عيد ميلاد أحلى وأجمل وأطيب بسبوسه في الدنيا كلها.. 🎂✨\", \"letter_content\": \"كل سنة وانتي طيبة يا أحلى وأجمل حاجة في حياتي ❤️\\nواحلا بنوته هتم كده كده  19\\nالنهارده يوم مش عادي خالص… ده اليوم اللي الدنيا نورت فيه عشان انتي جيتي فيها ✨\\n\\nبجد أنا مش عارف أقولك إيه ولا أبدأ منين… بس اللي متأكد منه إنك أحلى نعمة ربنا رزقني بيها. وجودك في حياتي فرق معايا في كل حاجة، في ضحكتي، في راحتي، وحتى في طريقة تفكيري… بقيت أشوف الدنيا أحلى عشان انتي فيها.\\n\\nفاكرة أول مرة نزلتي فيها؟ كنا فاكرين إنها شوية أيام وبنتسلى وخلاص وكل واحد هيروح لحاله… بس سبحان الله، الأيام جريت بينا، واهو عدى على الكلام ده ٦ شهور، وكل يوم فيها حبنا بيكبر أكتر من اللي قبله  حابب أقولك اني هفضل جنبك عمر كلو مهما حصل ومش هسيبك ابدا وكل سنه ونتي في حضني وحياتي كلها بحبكككككك🔐👑🌝🎁🎊\"}, \"wishes\": {\"items\": [{\"tags\": [\"حبي الأبدي ✨\", \"حبنا بيكبر ❤️\"], \"text\": \"كل سنة وأنتِ جوة قلبي، كل عام وأنتِ حبي الأول والأخير وروحي وسر ضحكتي وسعادتي يا كل حياتي...\"}, {\"tags\": [\"دنيتي الجميلة 🌱\", \"سند وعمر 🙌\"], \"text\": \"يا رب يباركلي في عمرك يا حبيبتي، ويخلي أيامنا كلها حب وضحكة حلوة وراحة بال على طول سوا.\"}, {\"tags\": [\"عشق ملوش آخر 🌹\", \"نور عيوني 💫\"], \"text\": \"يا نور عيني ويا حتة من روحي، كل سنة وأنتِ طيبة ومعايا وجنبي، ومنورالي حياتي يا أغلى وأجمل ما عندي في الدنيا.\"}, {\"tags\": [\"نبض واحد 💞\", \"حبيبة قلبي 🔗\"], \"text\": \"أنتِ مش بس فرحة يوم ميلادك، أنتِ فرحة العمر كله اللي كنت بتمناها، ربنا يديمك ليا يا أحلى حاجة حصلتلي.\"}], \"title\": \"• أمنية خاصة\", \"items_text\": \"كل سنة وأنتِ جوة قلبي، كل عام وأنتِ حبي الأول والأخير وروحي وسر ضحكتي وسعادتي يا كل حياتي... | حبي الأبدي ✨, حبنا بيكبر ❤️\\nيا رب يباركلي في عمرك يا حبيبتي، ويخلي أيامنا كلها حب وضحكة حلوة وراحة بال على طول سوا. | دنيتي الجميلة 🌱, سند وعمر 🙌\\nيا نور عيني ويا حتة من روحي، كل سنة وأنتِ طيبة ومعايا وجنبي، ومنورالي حياتي يا أغلى وأجمل ما عندي في الدنيا. | عشق ملوش آخر 🌹, نور عيوني 💫\\nأنتِ مش بس فرحة يوم ميلادك، أنتِ فرحة العمر كله اللي كنت بتمناها، ربنا يديمك ليا يا أحلى حاجة حصلتلي. | نبض واحد 💞, حبيبة قلبي 🔗\"}, \"countdown\": {\"title\": \"• العد التنازلي المنتظر\", \"target_date\": \"2026-07-30T00:00:00+03:00\", \"pending_text\": \"الوقت المتبقي على عيد ميلاد اجمل انسانه في الكون 💖\", \"completed_text\": \"يوم ميلادكِ السعيد بدأ الآن.. جعل الله كل أيامكِ فرحة وسروراً بجانبي ونبضات حبنا لا تنتهي أبداً! 💖✨\", \"completed_title\": \"🎉🎂 كل عام وأنتِ أسعد وأجمل يا بسبوسه! 🎂🎉\"}}','2026-07-29 16:28:33','2026-07-29 21:17:31'),(19,'8530','fawzya-ahmed','فوزيه','احمد',1,0,'ar','modern','romantic','{\"hero\": {\"quote\": \"\\\"عامك الجديد وعمري ما يكملوش غير بنور عينيكي وضحكة قلبك الصافية\\\"\", \"kicker\": \"احتفالاً بيوم ميلادك المميز 💖\", \"birthdate\": \"08 • 09 • 2007\", \"avatar_image\": null, \"avatar_title\": \"سامية\", \"banner_image\": \"/assets/images/birthday_banner.png\", \"avatar_subtitle\": \"فوزيه سر سعادتي وعمري 🌹\"}, \"album\": {\"title\": \"• ألبوم الذكريات\", \"images\": [\"http://localhost/storage/invitations/gallery/5cXXaI5RD4wdUEadIQu69k48J6qhYaDSWOysJwG8.jpg\", \"http://localhost/storage/invitations/gallery/Loc71vINyUJXj4IMg9pwCJRAfM5pWZa0X1ueTdIf.jpg\", \"http://localhost/storage/invitations/gallery/bvk3W3HzPGwOFaSGWQoxa8x75SD4pAE77SlqrQix.jpg\", \"http://localhost/storage/invitations/gallery/TkyfgJhfvFvHmZd0MxZA59TuHV6WYJbzzlwpYA45.jpg\", \"http://localhost/storage/invitations/gallery/zuBfngq1LnAR1skOsCZaBa6CyViisaJrWa09PfBK.jpg\", \"http://localhost/storage/invitations/gallery/fflDTTdHTjOjX7aSmR0mlfTxulehJMAlPndF9szt.jpg\", \"http://localhost/storage/invitations/gallery/vQ2g4lQ7sVgbCHX7lIxaBHZM64tFqgF3LtbS1iOi.jpg\"], \"description\": \"صور محفورة في القلب، ولحظات لا تُنسى بتفاصيلها الجميلة. اضغطي على أي صورة لرؤيتها بوضوح وحفظها كذكرى مخلدة 🌹\", \"images_text\": \"http://localhost/storage/invitations/gallery/5cXXaI5RD4wdUEadIQu69k48J6qhYaDSWOysJwG8.jpg\\nhttp://localhost/storage/invitations/gallery/Loc71vINyUJXj4IMg9pwCJRAfM5pWZa0X1ueTdIf.jpg\\nhttp://localhost/storage/invitations/gallery/bvk3W3HzPGwOFaSGWQoxa8x75SD4pAE77SlqrQix.jpg\\nhttp://localhost/storage/invitations/gallery/TkyfgJhfvFvHmZd0MxZA59TuHV6WYJbzzlwpYA45.jpg\\nhttp://localhost/storage/invitations/gallery/zuBfngq1LnAR1skOsCZaBa6CyViisaJrWa09PfBK.jpg\\nhttp://localhost/storage/invitations/gallery/fflDTTdHTjOjX7aSmR0mlfTxulehJMAlPndF9szt.jpg\\nhttp://localhost/storage/invitations/gallery/vQ2g4lQ7sVgbCHX7lIxaBHZM64tFqgF3LtbS1iOi.jpg\"}, \"audio\": {\"url\": \"https://youtu.be/fp3DqbNVOxo?si=Wu0Co5qV7rWv5YqK\"}, \"basic\": {\"passcode\": \"3112025\"}, \"footer\": {\"text\": \"شكراً لمشاركتنا لحظاتكم السعيدة 🌹\", \"whatsapp\": null}, \"letter\": {\"title\": \"رسالة حب سرية مخصصة لفوزيه 💖\", \"description\": \"اضغطي على الختم في المنتصف لفتح الرسالة الخاصة والاستماع للألحان 💌\", \"love_phrase\": \"بحبك ❤️\", \"letter_title\": \"عيد ميلاد أحلى وأجمل وأطيب حد في الدنيا كلها.. 🎂✨\", \"letter_content\": \"كل سنة وإنتي معايا ❤️\\nكل سنة وإنتي طيبة،\\nكل سنة وإنتي أم صاصا 😂❤️\\nم. م. غ\\n\\nبحبك يا حبيبتي ❤️\\n\\nالنهارده أول أيام الـ19، وعقبال كل اللي جاي من عمرك يا فوفتي، وربنا يجمعنا على خير يا رب ❤️\\n\\nالسنة دي مختلفة بالنسبالي، عشان أنا موجود فيها معاكي، وإن شاء الله أفضل موجود في كل سنة جاية من عمرك.\\n\\nوالسنة الجاية تتمي الـ20 سنة، وتبقي حبيبتي كبرت وبقت عروسة، وأحتفل أنا بعيد ميلادك وأنا جنبك ❤️\\n\\nويطول بينا العمر، ونفضل نحتفل بعيد ميلادك سنة ورا سنة، لحد ما نحتفل بيه مع ولادنا في بيتنا، ونفتكر سوا كل السنين اللي عدت علينا ❤️\\n\\nيمكن مش دايمًا بعرف أقولك كل اللي جوايا، وممكن أوقات أضايقك أو أقصر من غير ما أقصد، بس صدقيني إنتي غالية عندي أكتر مما الكلام يقدر يوصف.\\n\\nربنا يطول في عمرك ويخليكي ليا، وتكبري يوم بعد يوم قدام عنيا، وأفضل أشوفك بتكبري وأفرح بكل سنة جديدة في عمرك.\\n\\nوتفضلي إنتي عمري اللي بيكبر كل يوم ❤️\\n\\nكل سنة وإنتي حبيبتي وفوفتي،\\nوكل سنة وإنتي معايا،\\nوإن شاء الله كل أعياد ميلادك الجاية أكون جنبك.\"}, \"wishes\": {\"items\": [{\"tags\": [\"حبي الأبدي ✨\", \"حبنا بيكبر ❤️\"], \"text\": \"كل سنة وأنتِ جوة قلبي، كل عام وأنتِ حبي الأول والأخير وروحي وسر ضحكتي وسعادتي يا كل حياتي...\"}, {\"tags\": [\"دنيتي الجميلة 🌱\", \"سند وعمر 🙌\"], \"text\": \"يا رب يباركلي في عمرك يا حبيبتي، ويخلي أيامنا كلها حب وضحكة حلوة وراحة بال على طول سوا.\"}, {\"tags\": [\"عشق ملوش آخر 🌹\", \"نور عيوني 💫\"], \"text\": \"يا نور عيني ويا حتة من روحي، كل سنة وأنتِ طيبة ومعايا وجنبي، ومنورالي حياتي يا أغلى وأجمل ما عندي في الدنيا.\"}, {\"tags\": [\"نبض واحد 💞\", \"حبيبة قلبي 🔗\"], \"text\": \"أنتِ مش بس فرحة يوم ميلادك، أنتِ فرحة العمر كله اللي كنت بتمناها، ربنا يديمك ليا يا أحلى حاجة حصلتلي.\"}], \"title\": \"• أمنية خاصة\", \"items_text\": \"كل سنة وأنتِ جوة قلبي، كل عام وأنتِ حبي الأول والأخير وروحي وسر ضحكتي وسعادتي يا كل حياتي... | حبي الأبدي ✨, حبنا بيكبر ❤️\\nيا رب يباركلي في عمرك يا حبيبتي، ويخلي أيامنا كلها حب وضحكة حلوة وراحة بال على طول سوا. | دنيتي الجميلة 🌱, سند وعمر 🙌\\nيا نور عيني ويا حتة من روحي، كل سنة وأنتِ طيبة ومعايا وجنبي، ومنورالي حياتي يا أغلى وأجمل ما عندي في الدنيا. | عشق ملوش آخر 🌹, نور عيوني 💫\\nأنتِ مش بس فرحة يوم ميلادك، أنتِ فرحة العمر كله اللي كنت بتمناها، ربنا يديمك ليا يا أحلى حاجة حصلتلي. | نبض واحد 💞, حبيبة قلبي 🔗\"}, \"countdown\": {\"title\": \"• العد التنازلي المنتظر\", \"target_date\": \"2026-09-08T00:00:00+03:00\", \"pending_text\": \"الوقت المتبقي على عيد ميلاد اجمل انسانه في الكون 💖\", \"completed_text\": \"يوم ميلادكِ السعيد بدأ الآن.. جعل الله كل أيامكِ فرحة وسروراً بجانبي ونبضات حبنا لا تنتهي أبداً! 💖✨\", \"completed_title\": \"🎉🎂 كل عام وأنتِ أسعد وأجمل يا سامية! 🎂🎉\"}}','2026-09-07 11:58:22','2026-09-07 12:16:01');
