INSERT INTO `eid_greetings` VALUES (1,'6033','walaa-abdullah','walaa','abdullah',1,'en','elegant','{\"hero\": {\"title\": \"A warm Eid greeting made just for you\", \"kicker\": \"Eid Mubarak\", \"subtitle\": \"A small digital celebration full of wishes, memories, and affection.\", \"banner_image\": null, \"primary_button\": \"Read wishes\", \"secondary_button\": \"Explore memories\"}, \"footer\": {\"text\": \"Made with love for Eid.\"}, \"pulses\": {\"empty\": \"No pulses yet. Send the first one.\", \"title\": \"Love pulses board\", \"button\": \"Send warm pulse\", \"music_on\": \"Pause Eid melody\", \"music_off\": \"Play Eid melody\", \"description\": \"Send a warm pulse and fill the greeting with floating hearts and petals.\"}, \"wishes\": {\"items\": [{\"tags\": [\"Eternal joy\", \"Warm wishes\"], \"text\": \"Every Eid, you are the joy I keep returning to.\"}, {\"tags\": [\"Blessings\", \"New love\"], \"text\": \"May this Eid bring us peace, tenderness, and a love that keeps blooming.\"}], \"title\": \"Eid wishes\", \"items_text\": \"Every Eid, you are the joy I keep returning to. | Eternal joy, Warm wishes\\nMay this Eid bring us peace, tenderness, and a love that keeps blooming. | Blessings, New love\"}, \"moments\": {\"items\": [{\"date\": \"First Eid night\", \"likes\": 42, \"title\": \"Eid lights\", \"category\": \"Eid memories\", \"imageUrl\": null, \"description\": \"Lanterns, warmth, and a quiet promise of a brighter year.\"}, {\"date\": \"Eid morning\", \"likes\": 56, \"title\": \"The red roses\", \"category\": \"Love gift\", \"imageUrl\": null, \"description\": \"A little bouquet carrying a lot of tenderness.\"}], \"title\": \"Eid memories\", \"items_text\": \"Eid lights | First Eid night | Eid memories | Lanterns, warmth, and a quiet promise of a brighter year. |  | 42\\nThe red roses | Eid morning | Love gift | A little bouquet carrying a lot of tenderness. |  | 56\"}, \"instrument\": {\"title\": \"Interactive instrument\", \"description\": \"Tap the 