INSERT INTO `invitations` VALUES (2,'3115','abdullah-walaa','{\"en\":\"abdullah\",\"ar\":\"Abdullah\"}','{\"en\":\"walaa\",\"ar\":\"Walaa\"}','{\"en\":\"Abdullah & Walaa\",\"ar\":\"abdullah & walaa\"}',1,'walaa','abdullah','modern-minimal','en','elegant','{\"ar\": {\"body\": \"بمشاركة عائلتينا، ندعوكم للاحتفال معنا بزفافنا.\", \"open\": \"افتح\", \"kicker\": \"نحن على موعد مع الزفاف\", \"save_date\": \"احفظ التاريخ\", \"view_details\": \"عرض التفاصيل\", \"open_invitation\": \"افتح دعوة الزفاف\"}, \"en\": {\"body\": \"Together with their families, invite you to celebrate their wedding.\", \"open\": \"Open\", \"kicker\": \"We are getting married\", \"save_date\": \"Save the Date\", \"view_details\": \"View Details\", \"open_invitation\": \"Open wedding invitation\"}}','{\"ar\": {\"open_prompt\": \"افتح جواب الدعوة\", \"prompt_kicker\": \"الدعوة جاهزة\"}, \"en\": {\"open_prompt\": \"Open the Invitation Letter\", \"prompt_kicker\": \"The Invitation Is Ready\"}}','{\"ar\": {\"date\": \"الجمعة، 30 أكتوبر 2026\", \"time\": \"8:00 مساءً\", \"title\": \"الموعد والمكان\", \"venue\": \"قاعة كليوباترا\", \"kicker\": \"تفاصيل الزفاف\", \"address\": \"العنوان\", \"map_url\": null, \"landmark\": \"علامة مميزة\", \"location\": \"مركز قطور، محافظة الغربية\", \"day_label\": \"يوم الزفاف\", \"map_title\": \"خرائط جوجل - قاعة كليوباترا\", \"description\": \"يسعدنا ويشرفنا أن تشاركونا هذه الليلة الجميلة مع عائلتينا.\", \"venue_label\": \"قاعة الحفل\", \"open_location\": \"فتح الموقع\", \"landmark_value\": \"بجوار محطة القطار\"}, \"en\": {\"date\": \"Friday, October 30, 2026\", \"time\": \"8:00 PM\", \"title\": \"When & Where\", \"venue\": \"Cleopatra Hall\", \"kicker\": \"Wedding Details\", \"address\": \"Address\", \"map_url\": null, \"landmark\": \"Nearby Landmark\", \"location\": \"Qutour Center, Gharbia Governorate\", \"day_label\": \"The Wedding Day\", \"map_title\": \"Google Maps - Cleopatra Hall\", \"description\": \"We would be honored to celebrate this beautiful evening with you and our families.\", \"venue_label\": \"The Venue\", \"open_location\": \"Open Location\", \"landmark_value\": \"Next to the train station\"}}','{\"ar\": {\"title\": \"قصة حبنا\", \"events\": [{\"date\": \"30/1/2026\", \"desc\": \"كانت البداية بكلمة مرحباً هادئة صنعت كل شيء.\", \"title\": \"أول لقاء\"}, {\"date\": \"31/1/2026\", \"desc\": \"في اللقاء الثاني بدأت القصة تبدو حقيقية.\", \"title\": \"ثاني لقاء\"}, {\"date\": \"8/2/2026\", \"desc\": \"خطوة مباركة شهدتها العائلة واحتضنها الحب.\", \"title\": \"قراءة الفاتحة\"}, {\"date\": \"13/2/2026\", \"desc\": \"أصبح الوعد رسمياً وبدأ فصل جديد من الحكاية.\", \"title\": \"الخطوبة\"}, {\"date\": \"2/10/2026\", \"desc\": \"يُكتب الوعد المقدس بفرح وإيمان وبركة العائلة.\", \"title\": \"عقد القران\"}, {\"date\": \"30/10/2026\", \"desc\": \"اليوم الذي نجتمع فيه للاحتفال ببداية العمر معاً.\", \"title\": \"حفل الزفاف\"}], \"kicker\": \"الرحلة\"}, \"en\": {\"title\": \"Our Love Story\", \"events\": [{\"date\": \"30/1/2026\", \"desc\": \"The first hello that quietly started everything.\", \"title\": \"First Meet\"}, {\"date\": \"31/1/2026\", \"desc\": \"A second meeting made the story feel real.\", \"title\": \"Second Meet\"}, {\"date\": \"8/2/2026\", \"desc\": \"A blessed step witnessed by family and love.\", \"title\": \"Reciting Al-Fatiha\"}, {\"date\": \"13/2/2026\", \"desc\": \"The promise became official, and the next chapter began.\", \"title\": \"The Engagement\"}, {\"date\": \"2/10/2026\", \"desc\": \"The sacred promise is written with joy, faith, and family blessings.\", \"title\": \"Marriage Contract Ceremony\"}, {\"date\": \"30/10/2026\", \"desc\": \"The day everyone gathers to celebrate the beginning of forever.\", \"title\": \"The Marriage Celebration\"}], \"kicker\": \"The Journey\"}}','{\"ar\": {\"title\": \"ذكريات\", \"image_urls\": [\"https://adequate-blessing-production-4ffe.up.railway.app/storage/invitations/gallery/z4oCEhMezKWqp3Y3pxeCaIUxZ6wOrWOW7ZME5HzT.jpg\", \"https://adequate-blessing-production-4ffe.up